/*!
 * Themeasy — Video
 *
 * Powers the click-to-load facade: on activation it swaps in a
 * privacy-enhanced iframe (youtube-nocookie / Vimeo dnt, allowlisted hosts
 * only) or a native <video>, cross-fading once the player reports ready. It
 * also upgrades the auto YouTube poster (maxresdefault) to hqdefault when
 * the high-res thumbnail does not exist. Lightbox mode is owned by the
 * Themeasy lightbox module (GLightbox on .glightbox); the ambient skin is
 * pure HTML/CSS, except that its autoplay loop is paused here under
 * prefers-reduced-motion (CSS cannot stop native media). With no JS the
 * facade is a plain link to the video; in the editor (--static) only the
 * safe poster fallback and the reduced-motion pause run.
 *
 * Exposes a re-entrant Themeasy.video.init(root) / reset(root); both are
 * idempotent and safe to re-run.
 *
 * @author Themeasy
 * @link https://themeasy.co
 * @since 1.0.0
 */

(function (window, document) {
  'use strict'

  window.Themeasy = window.Themeasy || {}
  window.Themeasy.video = window.Themeasy.video || {}

  const SELECTOR_WIDGET = '.tms-video'
  const CLASS_STATIC = 'tms-video--static'
  const CLASS_PLAYING = 'tms-video--playing'

  // Only these origins may ever be injected as an iframe src.
  const EMBED_HOSTS = [
    'https://www.youtube-nocookie.com/',
    'https://player.vimeo.com/'
  ]

  // ------------------------------------------------------------------------
  // Utils
  // ------------------------------------------------------------------------
  function onDomReady(fn) {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', fn, { once: true })
      return
    }
    fn()
  }

  function isAllowedEmbed(url) {
    return EMBED_HOSTS.some(function (host) {
      return typeof url === 'string' && url.indexOf(host) === 0
    })
  }

  // ------------------------------------------------------------------------
  // Poster fallback
  // ------------------------------------------------------------------------

  /**
   * Swap the auto YouTube poster to its fallback when maxresdefault is
   * missing — either a straight 404 (error event) or YouTube's tiny gray
   * placeholder (a successful load at thumbnail size).
   *
   * @param {HTMLElement} wrapper The .tms-video element.
   */
  function bindPosterFallback(wrapper) {
    const poster = wrapper.querySelector('.tms-video__poster[data-poster-fallback]')
    if (!poster || poster.dataset.tmsPosterChecked === '1') return

    poster.dataset.tmsPosterChecked = '1'

    const swap = function () {
      const fallback = poster.getAttribute('data-poster-fallback')
      if (fallback && poster.src !== fallback) poster.src = fallback
    }
    const checkSize = function () {
      if (poster.naturalWidth > 0 && poster.naturalWidth <= 120) swap()
    }

    poster.addEventListener('error', swap, { once: true })
    poster.addEventListener('load', checkSize, { once: true })

    // The image may have settled before we bound the listeners.
    if (poster.complete) {
      if (poster.naturalWidth === 0) swap()
      else checkSize()
    }
  }

  // ------------------------------------------------------------------------
  // Ambient loop vs. reduced motion
  // ------------------------------------------------------------------------

  /**
   * Pause the ambient autoplay loop for visitors who ask for reduced motion —
   * the poster (or first frame) stays as a still. CSS cannot stop native
   * media, so this is the JS half of the reduced-motion contract.
   *
   * @param {HTMLElement} wrapper The .tms-video element.
   */
  function pauseAmbientForReducedMotion(wrapper) {
    if (!window.matchMedia || !window.matchMedia('(prefers-reduced-motion: reduce)').matches) return

    const video = wrapper.querySelector('.tms-video__player--ambient')
    if (!video) return

    video.autoplay = false
    video.removeAttribute('autoplay')

    const stop = function () { video.pause() }
    stop()
    video.addEventListener('loadeddata', stop, { once: true })
  }

  // ------------------------------------------------------------------------
  // On-demand player
  // ------------------------------------------------------------------------

  function buildIframe(url, title) {
    const iframe = document.createElement('iframe')
    iframe.className = 'tms-video__player'
    iframe.src = url
    iframe.title = title || 'Video'
    iframe.setAttribute('allow', 'autoplay; fullscreen; picture-in-picture; encrypted-media')
    iframe.setAttribute('allowfullscreen', '')
    return iframe
  }

  function buildVideo(facade) {
    const video = document.createElement('video')
    video.className = 'tms-video__player'
    video.src = facade.getAttribute('data-video-src')
    video.controls = facade.getAttribute('data-controls') !== 'false'
    video.muted = facade.getAttribute('data-muted') === 'true'
    video.loop = facade.getAttribute('data-loop') === 'true'
    video.autoplay = true
    video.playsInline = true
    return video
  }

  /**
   * Replace the facade with the real player. Returns false when nothing can
   * be built so the click falls through to the plain link.
   *
   * @param {HTMLElement} wrapper The .tms-video element.
   * @param {HTMLElement} facade  The .tms-video__facade anchor.
   * @return {boolean} Whether a player was injected.
   */
  function activate(wrapper, facade) {
    if (wrapper.classList.contains(CLASS_PLAYING)) return true

    const frame = wrapper.querySelector('.tms-video__frame')
    if (!frame) return false

    const embedUrl = facade.getAttribute('data-embed-url')
    let player = null

    if (embedUrl && isAllowedEmbed(embedUrl)) {
      player = buildIframe(embedUrl, facade.getAttribute('aria-label'))
    } else if (facade.getAttribute('data-video-src')) {
      player = buildVideo(facade)
    }

    if (!player) return false

    let revealed = false
    const reveal = function () {
      if (revealed) return
      revealed = true
      wrapper.classList.add(CLASS_PLAYING)
      facade.setAttribute('aria-hidden', 'true')
      facade.setAttribute('tabindex', '-1')
      if (typeof player.focus === 'function') player.focus({ preventScroll: true })
    }

    if (player.tagName === 'IFRAME') {
      player.addEventListener('load', reveal, { once: true })
    } else {
      player.addEventListener('loadeddata', reveal, { once: true })
      const played = player.play()
      if (played && typeof played.catch === 'function') played.catch(function () {})
    }

    // Safety net: reveal even if the ready event never fires.
    window.setTimeout(reveal, 1200)

    frame.appendChild(player)
    return true
  }

  // ------------------------------------------------------------------------
  // Instance wiring
  // ------------------------------------------------------------------------

  function buildInstance(wrapper) {
    // Safe everywhere, including the editor preview.
    bindPosterFallback(wrapper)
    pauseAmbientForReducedMotion(wrapper)

    if (wrapper.classList.contains(CLASS_STATIC)) return
    if (wrapper.dataset.tmsVideoBound === '1') return

    const facade = wrapper.querySelector('.tms-video__facade')
    if (!facade) return // Ambient skin: nothing to wire.

    wrapper.dataset.tmsVideoBound = '1'

    // Lightbox mode: the Themeasy lightbox module owns the click.
    if (facade.classList.contains('glightbox')) return

    facade.addEventListener('click', function (event) {
      // Modified clicks keep native link behavior (open in new tab, etc.).
      if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return

      if (activate(wrapper, facade)) event.preventDefault()
    })
  }

  /**
   * Initialize every video facade inside a given scope.
   *
   * @param {HTMLElement} [root] Optional scope — defaults to document.
   */
  window.Themeasy.video.init = function (root) {
    const scope = root || document
    const widgets = scope.querySelectorAll(SELECTOR_WIDGET)
    if (!widgets.length) return

    widgets.forEach(buildInstance)
  }

  /**
   * Remove injected players and restore facades so init() can run fresh
   * (used when a widget re-renders).
   *
   * @param {HTMLElement} [root] Optional scope — defaults to document.
   */
  window.Themeasy.video.reset = function (root) {
    const scope = root || document
    const widgets = scope.querySelectorAll(SELECTOR_WIDGET)
    if (!widgets.length) return

    widgets.forEach(function (wrapper) {
      delete wrapper.dataset.tmsVideoBound
      wrapper.classList.remove(CLASS_PLAYING)

      wrapper.querySelectorAll('.tms-video__player:not(.tms-video__player--ambient)').forEach(function (player) {
        player.remove()
      })

      const facade = wrapper.querySelector('.tms-video__facade')
      if (facade) {
        facade.removeAttribute('aria-hidden')
        facade.removeAttribute('tabindex')
      }
    })
  }

  // ------------------------------------------------------------------------
  // Central boot
  // ------------------------------------------------------------------------
  function boot() {
    if (document.querySelector(SELECTOR_WIDGET)) {
      window.Themeasy.video.init()
    }
  }

  window.Themeasy.video.boot = boot
  onDomReady(boot)
})(window, document)
